'use strict';

var index = require('./index-OWCBTetj.js');

const sidebarTitleCss = () => `:host{position:relative;display:var(--ifx-sidebar-title-display, block)}:host([data-show-in-collapsed=true]){display:var(--ifx-sidebar-title-show-in-collapsed-display, block)}.sidebar__title{width:100%;height:fit-content;border-top:1px solid #eeeded;padding:var(--ifx-sidebar-title-padding, 12px 0)}.sidebar__title.no-top-border{border-top:none}.sidebar__title-label{min-height:20px;font:600 0.875rem/1.25rem "Source Sans 3";font-family:var(--ifx-font-family);text-transform:uppercase;color:#575352;letter-spacing:3px;display:var(--ifx-sidebar-title-label-display, block);word-break:break-all}`;

const SidebarTitle = class {
    constructor(hostRef) {
        index.registerInstance(this, hostRef);
    }
    get el() { return index.getElement(this); }
    /** Show item/content when the sidebar is collapsed */
    showInCollapsed = false;
    componentWillLoad() {
        // Set data attribute for CSS targeting
        this.el.setAttribute("data-show-in-collapsed", this.showInCollapsed.toString());
    }
    render() {
        return (index.h("div", { key: 'f122aab90afd99af005d4a453db7166ce8fbfd0a', class: "sidebar__title" }, index.h("div", { key: 'aec7f771e1a8e456ee37f19b276e0412148f2a85', class: "sidebar__title-label" }, index.h("slot", { key: 'e5e52f7e8f440ad728f26abe1030581eab7cbff5' }))));
    }
};
SidebarTitle.style = sidebarTitleCss();

exports.ifx_sidebar_title = SidebarTitle;
